export const DEFAULT_TIMEPICKER_OPTIONS = {
  mode: 'listbox', // list, listbox, detailed
  selection: 'single', // single/multiple
  start: '00:00',
  end: '24:00',
  interval: '30m', // m or h
  format: 'hh:mm', // HH == 24h clock hh == 12h clock mm = minutes ss = seconds
  blockedTimes: [], // Example blocked interval
  showBlockedTimes: true,
}

export const DEFAULT_TIMEPICKER_DISCLOSURE_OPTS = {
  showOnClick: true,
  focusTriggerOnClose: false,
  shiftTabBackToContent: false,
}

export function detailedTimepicker(node, options = {}) {}

export function generateTimings(options = {}) {
  options = Object.assign({}, DEFAULT_TIMEPICKER_OPTIONS, options)
  const { start, end, interval, format, blockedTimes, showBlockedTimes } =
    options

  // Initialize timings array
  const timings = []
  const intervalInMinutes =
    parseInt(interval, 10) * (interval.includes('h') ? 60 : 1)
  const blockedMinutes = blockedTimes.map(([start, end]) => {
    return [timeStringToMinutes(start), timeStringToMinutes(end)]
  })

  for (
    let minutes = timeStringToMinutes(start);
    minutes <= timeStringToMinutes(end);
    minutes += intervalInMinutes
  ) {
    const time = {
      minutes,
      timeString: minutesToTimeString(minutes, format),
      timeString24H: minutesToTimeString(minutes, 'HH:mm'),
    }
    const blocked = isBlockedMinutes(minutes, blockedMinutes)
    if (showBlockedTimes) timings.push({ ...time, blocked })
    else {
      if (!blocked) {
        timings.push({ ...time, blocked: false })
      }
    }
  }

  return timings
}

// Helper function to convert time string to minutes
function timeStringToMinutes(time) {
  const [hours, minutes] = time.split(':').map(Number)
  return hours * 60 + minutes
}

// Helper function to convert minutes back to time string
function minutesToTimeString(minutes, format) {
  let hours = Math.floor(minutes / 60)
  const mins = minutes % 60
  const seconds = 0 // Assuming seconds are always 0 as input is in minutes
  const timestringParts = []

  // Adjust for the 24:00 case to correctly represent it as 00:00
  if (hours === 24) hours = 0

  // Determine if AM/PM is needed
  const isAmPm = format.includes('h') || format.includes('hh')
  const ampm = hours >= 12 ? 'PM' : 'AM'

  // Define time components based on the format
  const timeComponents = {
    HH: hours.toString().padStart(2, '0'),
    H: hours.toString(),
    hh: (hours % 12 || 12).toString().padStart(2, '0'),
    h: (hours % 12 || 12).toString(),
    mm: mins.toString().padStart(2, '0'),
    m: mins.toString(),
    ss: seconds.toString().padStart(2, '0'),
    s: seconds.toString(),
  }

  if (format.includes('H')) {
    if (format.includes('HH')) timestringParts.push(timeComponents.HH)
    else timestringParts.push(timeComponents.H)
  }

  if (format.includes('h')) {
    if (format.includes('hh')) timestringParts.push(timeComponents.hh)
    else timestringParts.push(timeComponents.h)
  }

  if (format.includes('m')) {
    if (format.includes('mm')) timestringParts.push(timeComponents.mm)
    else timestringParts.push(timeComponents.m)
  }

  if (format.includes('s')) {
    if (format.includes('ss')) timestringParts.push(timeComponents.ss)
    else timestringParts.push(timeComponents.s)
  }

  // Join the parts with colon separator and append AM/PM if needed
  let timeString = timestringParts.join(':')
  if (isAmPm) timeString += ` ${ampm}`

  return timeString
}

// Check if a time is within any blocked intervals
function isBlockedMinutes(minutes, blockedIntervals) {
  return blockedIntervals.some(([startMinutes, endMinutes]) => {
    return minutes >= startMinutes && minutes <= endMinutes
  })
}
